import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as r,b as t,c as i,d as o}from"./chunks/M-STA5.Cj8YAhfJ.js";import{_ as u,o as n,c as l,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Statistiques","description":"","frontmatter":{"source_hash":"cf4c58239c","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/use/statistics.md","filePath":"fr/use/statistics.md"}'),p={name:"fr/use/statistics.md"};function d(m,e,g,_,h,b){return n(),l("div",null,[...e[0]||(e[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Statistiques</p></div><p>L&#39;écran Statistiques propose 3 affichages statistiques de base que vous pouvez configurer pour différentes périodes.</p><ol><li>Sélectionnez d&#39;abord la période sur laquelle calculer les statistiques : aujourd&#39;hui, hier, les 7, 30 ou 90 derniers jours.</li><li>Vous pouvez afficher le graphique en plein écran (appuyez à nouveau dessus pour quitter le mode plein écran).</li><li>Vous pouvez partager l&#39;écran sous forme de capture d&#39;écran.</li></ol><img src="'+a+'" style="zoom:75%;"><br><p>Le premier écran affiche vos chiffres.</p><img src="'+r+'" style="zoom:75%;"><p>Le pourcentage dans la cible est calculé à partir de la plage entre les valeurs basse et haute définies dans Menu - Unité de glycémie.<br> Les nombres absolus comptent les mesures dans la cible, au-dessus et en dessous.<br> La glycémie médiane est la valeur centrale de vos données : il y a autant de mesures au-dessus qu&#39;en dessous.<br> La glycémie moyenne est la moyenne arithmétique de toutes les mesures.<br> L&#39;HbA1c estimée n&#39;est qu&#39;un calcul mathématique basé sur la glycémie moyenne, converti en mmol/mol ou en pourcentage.<br> StdDev, ou écart-type, est le résultat du calcul mathématique. Il montre la dispersion de vos glycémies.<br> Le SD relatif (CV) est l&#39;écart-type divisé par la moyenne ; il montre lui aussi la dispersion de vos mesures.<br> GVI et PGS sont des paramètres introduits par Dexcom, voir <a href="https://web.archive.org/web/20160523152519/http://www.healthline.com/diabetesmine/a-new-view-of-glycemic-variability-how-long-is-your-line" target="_blank" rel="noreferrer">ici</a>.</p><p>Consultez <a href="https://diatribe.org/understanding-average-glucose-standard-deviation-cv-and-blood-sugar-variability" target="_blank" rel="noreferrer">cette page</a> pour des explications sur ces paramètres, et n&#39;oubliez pas qu&#39;ils sont basés sur les mesures et dépendent de leur qualité. De mauvaises mesures (imprécises) donneront de mauvaises statistiques, que ce soit à cause de la précision du capteur ou de vos étalonnages.</p><p>Vous pouvez choisir les valeurs affichées. Appuyez sur le menu (⋮) en haut à droite et sélectionnez <code>Parameters</code>, puis cochez ou décochez : Absolute #s, Median BG, Estimated A1C, Relative SD, GVI, PGS, Standard Deviation.</p><br><p>Balayez vers la gauche pour voir une représentation graphique de votre pourcentage dans la cible.<br> Le vert correspond à la cible, le jaune au-dessus et le rouge en dessous.</p><img src="'+t+'" style="zoom:75%;"><br><p>Balayez à nouveau pour voir le graphique des percentiles.</p><img src="'+i+'" style="zoom:75%;"><p>Tournez l&#39;écran pour un meilleur affichage.</p><img src="'+o+'" style="zoom:50%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Dernière modification le 6/7/2026</em></a></p>',20)])])}const q=u(p,[["render",d]]);export{z as __pageData,q as default};
